import { readFileSync } from "node:fs";

import type { APIRequestContext } from "@playwright/test";

import { expect, sample, test, uniqueName } from "../../fixtures";

type DocumentOut = { id: string; kind: string; status: string };

async function createInReviewVendor(member: APIRequestContext): Promise<{ id: string; extractionIds: Record<string, string> }> {
  const created = await member.post("/api/vendors", {
    data: {
      name: uniqueName("REV-06 Vendor"),
      category: "services",
      contact_email: `rev06.${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}@example.com`,
    },
  });
  expect(created.status(), await created.text()).toBe(201);
  const vendorId = ((await created.json()) as { id: string }).id;

  const uploads: [string, string][] = [
    ["w9", "w9.txt"],
    ["insurance_certificate", "insurance_certificate.txt"],
    ["contract", "contract.txt"],
  ];
  for (const [kind, file] of uploads) {
    const upload = await member.post(`/api/vendors/${vendorId}/documents`, {
      multipart: {
        kind,
        file: { name: file, mimeType: "text/plain", buffer: readFileSync(sample(file)) },
      },
    });
    expect(upload.status(), await upload.text()).toBe(201);
  }

  // Extraction runs in the background; wait until all three documents are extracted.
  await expect
    .poll(async () => {
      const res = await member.get(`/api/vendors/${vendorId}/documents`);
      const docs = (await res.json()) as DocumentOut[];
      return docs.filter((d) => d.status === "extracted").length;
    }, { timeout: 60_000 })
    .toBe(3);

  const submitted = await member.post(`/api/vendors/${vendorId}/submit`);
  expect(submitted.status(), await submitted.text()).toBe(200);

  const docsRes = await member.get(`/api/vendors/${vendorId}/documents`);
  const docs = (await docsRes.json()) as DocumentOut[];
  const extractionIds: Record<string, string> = {};
  for (const doc of docs) {
    const extractionRes = await member.get(`/api/documents/${doc.id}/extraction`);
    expect(extractionRes.status(), await extractionRes.text()).toBe(200);
    extractionIds[doc.kind] = ((await extractionRes.json()) as { id: string }).id;
  }
  return { id: vendorId, extractionIds };
}

test("rejecting an extraction requires a note and returns the vendor to the member", { tag: "@REV-06" }, async ({ apiAs }) => {
  // Arrange
  const member = await apiAs("member");
  const reviewer = await apiAs("reviewer");
  const vendor = await createInReviewVendor(member);
  const w9Id = vendor.extractionIds["w9"];
  expect(w9Id, "W-9 extraction exists").toBeTruthy();

  // Act: reject without a note
  const withoutNote = await reviewer.post(`/api/extractions/${w9Id}/decision`, {
    data: { decision: "reject" },
  });

  // Assert
  expect(withoutNote.status(), await withoutNote.text()).toBe(422);

  // Act: reject with a note
  const withNote = await reviewer.post(`/api/extractions/${w9Id}/decision`, {
    data: { decision: "reject", note: "Tax ID does not match" },
  });

  // Assert
  expect(withNote.status(), await withNote.text()).toBe(200);
  await expect
    .poll(async () => {
      const res = await member.get(`/api/vendors/${vendor.id}`);
      return ((await res.json()) as { status: string }).status;
    })
    .toBe("rejected");

  const auditRes = await member.get(`/api/vendors/${vendor.id}/audit`);
  expect(auditRes.status(), await auditRes.text()).toBe(200);
  const actions = ((await auditRes.json()) as { items: { action: string }[] }).items.map((i) => i.action);
  expect(actions, "audit trail").toContain("extraction.rejected");
});
